#!/bin/sh
# The peer at 10.77.0.1 in the tunnel 10.77.0.0/24. It is the only way to internal-a from outside:
# 10.77.0.1:22 inside the tunnel forwards to internal-a's SSH, and its DNS answers every name under
# lab.vpn with 10.77.0.1, so a host named internal-a.lab.vpn can only be found through the tunnel.
# The keys come from scripts/test-hosts/.env (generated by ./scripts/test-hosts.sh up).
set -eu
: "${WG_SERVER_PRIVATE_KEY:?}" "${WG_CLIENT_PUBLIC_KEY:?}"

export WG_I_PREFER_BUGGY_USERSPACE_TO_POLISHED_KMOD=1
wireguard-go -f wg0 &
for _ in $(seq 1 50); do ip link show wg0 >/dev/null 2>&1 && break; sleep 0.1; done

umask 077
printf '%s\n' "$WG_SERVER_PRIVATE_KEY" >/run/wg.key
wg set wg0 listen-port 51820 private-key /run/wg.key peer "$WG_CLIENT_PUBLIC_KEY" allowed-ips 10.77.0.2/32
rm -f /run/wg.key
ip address add 10.77.0.1/24 dev wg0
ip link set mtu 1420 up dev wg0

socat TCP-LISTEN:22,bind=10.77.0.1,fork,reuseaddr TCP:internal-a:2222 &
dnsmasq --keep-in-foreground --listen-address=10.77.0.1 --bind-interfaces --no-resolv --no-hosts \
  --address=/lab.vpn/10.77.0.1 &
echo "wireguard peer ready on 10.77.0.1"
wait
